const FILES = {
  "weekly-meal-planner.pdf": SINGLE_WEEK,
  "meal-planner-5-weeks.pdf": FIVE_WEEKS,
  "weekend-batch-cooking.pdf": BATCH_COOKING,
  "grocery-list-pack.pdf": GROCERY_LISTS,
} as const;

export type DemoFileName = keyof typeof FILES;

export function getDemoFile(name: DemoFileName): Uint8Array {
  return Uint8Array.from(Buffer.from(FILES[name].join(""), "base64"));
}
